import React, { useState, useEffect } from "react";
import Login from "./components/login";
import IncomeCategory from "./components/IncomeCategory";
import SpendingPriority from "./components/SpendingPriority";
import BudgetLimits from "./components/BudgetLimits";
import Dashboard from "./components/Dashboard";
import Questionnaire from "./components/Questionnaire";

function App() {
  const [step, setStep] = useState("login");

  const [data, setData] = useState({
    income: "",
    categories: [],
    priorities: [],
    limits: {},
    email: ""
  });

  // ✅ CHECK IF USER ALREADY EXISTS
  useEffect(() => {
    const savedUser = JSON.parse(localStorage.getItem("userData"));
    if (savedUser) {
      setData(savedUser);
      setStep("dashboard"); // 🔥 skip onboarding
    }
  }, []);

  // ✅ SAVE USER DATA AFTER FINAL STEP
  const saveUser = (finalData) => {
    localStorage.setItem("userData", JSON.stringify(finalData));
    setData(finalData);
    setStep("dashboard");
  };

  return (
    <>
      {step === "login" && (
        <Login
          onLogin={(email) => {
            setData({ ...data, email });
            setStep("income");
          }}
        />
      )}

      {step === "income" && (
        <IncomeCategory
          onNext={(val) => {
            setData({ ...data, income: val });
            setStep("questionnaire");
          }}
        />
      )}

      {step === "questionnaire" && (
        <Questionnaire
          onNext={(answers) => {
            setData({ ...data, questionnaire: answers });
            setStep("priority");
          }}
          onBack={() => setStep("income")}
        />
      )}

      {step === "priority" && (
        <SpendingPriority
          onNext={(priorities) => {
            setData({ ...data, priorities });
            setStep("budget");
          }}
          onBack={() => setStep("questionnaire")}
        />
      )}

      {step === "budget" && (
        <BudgetLimits
          selectedCategories={data.categories}
          onNext={(limits) => {
            const finalData = { ...data, limits };
            saveUser(finalData); // 🔥 SAVE HERE
          }}
          onBack={() => setStep("priority")}
        />
      )}

      {step === "dashboard" && (
        <Dashboard userData={data} setUserData={setData} />
      )}
    </>
  );
}

export default App;
